var DEFAULT_TERMINAL_SETTINGS = {
  themeId: 'tokyo-night',
  fontFamily: 'Consolas, "Courier New", monospace',
  fontSize: 13,
  scrollback: 5000,
  cursorBlink: true,
};

function loadTerminalSettings() {
  try {
    const raw = JSON.parse(localStorage.getItem(THEME_STORAGE_KEY) || 'null');
    if (!raw || typeof raw !== 'object') return { ...DEFAULT_TERMINAL_SETTINGS };
    const themeId = BUILTIN_THEMES[raw.themeId] ? raw.themeId : DEFAULT_TERMINAL_SETTINGS.themeId;
    const fontSize = Number(raw.fontSize);
    const scrollback = Number(raw.scrollback);
    return {
      themeId,
      fontFamily: typeof raw.fontFamily === 'string' && raw.fontFamily.trim()
        ? raw.fontFamily.trim().slice(0, 120)
        : DEFAULT_TERMINAL_SETTINGS.fontFamily,
      fontSize: Number.isFinite(fontSize) ? Math.min(32, Math.max(10, Math.round(fontSize))) : DEFAULT_TERMINAL_SETTINGS.fontSize,
      scrollback: Number.isFinite(scrollback) ? Math.min(100000, Math.max(500, Math.round(scrollback))) : DEFAULT_TERMINAL_SETTINGS.scrollback,
      cursorBlink: raw.cursorBlink !== false,
    };
  } catch {
    return { ...DEFAULT_TERMINAL_SETTINGS };
  }
}

function saveTerminalSettings(settings) {
  const next = { ...DEFAULT_TERMINAL_SETTINGS, ...settings };
  if (!BUILTIN_THEMES[next.themeId]) next.themeId = DEFAULT_TERMINAL_SETTINGS.themeId;
  localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(next));
  return next;
}

function getTerminalOptions() {
  const s = loadTerminalSettings();
  const builtin = BUILTIN_THEMES[s.themeId] || BUILTIN_THEMES['tokyo-night'];
  return {
    fontSize: s.fontSize,
    fontFamily: s.fontFamily,
    cursorBlink: s.cursorBlink,
    scrollback: s.scrollback,
    allowProposedApi: true,
    theme: { ...builtin.theme },
  };
}

function applySettingsToTerminal(term, settings) {
  if (!term) return;
  const s = settings || loadTerminalSettings();
  const builtin = BUILTIN_THEMES[s.themeId] || BUILTIN_THEMES['tokyo-night'];
  try {
    term.options.fontFamily = s.fontFamily;
    term.options.fontSize = s.fontSize;
    term.options.scrollback = s.scrollback;
    term.options.cursorBlink = s.cursorBlink;
    term.options.theme = { ...builtin.theme };
  } catch (e) { /* older xterm */ }
}

function applySettingsToAllTerminals(settings) {
  const s = settings || loadTerminalSettings();
  const list = (typeof tabs !== 'undefined' && Array.isArray(tabs)) ? tabs : [];
  for (const tab of list) {
    if (tab.term) applySettingsToTerminal(tab.term, s);
    for (const pane of (tab.extraPanes || [])) {
      if (pane.term) applySettingsToTerminal(pane.term, s);
    }
    try { if (tab.fitAddon) tab.fitAddon.fit(); } catch {}
    for (const pane of (tab.extraPanes || [])) {
      try { if (pane.fitAddon) pane.fitAddon.fit(); } catch {}
    }
  }
}

function fillSettingsForm(settings) {
  const s = settings || loadTerminalSettings();
  const themeSel = document.getElementById('set-theme');
  const fontFamily = document.getElementById('set-font-family');
  const fontSize = document.getElementById('set-font-size');
  const scrollback = document.getElementById('set-scrollback');
  const cursorBlink = document.getElementById('set-cursor-blink');
  if (themeSel) {
    themeSel.innerHTML = Object.entries(BUILTIN_THEMES)
      .map(([id, t]) => `<option value="${id}">${t.name}</option>`)
      .join('');
    themeSel.value = s.themeId;
  }
  if (fontFamily) fontFamily.value = s.fontFamily;
  if (fontSize) fontSize.value = String(s.fontSize);
  if (scrollback) scrollback.value = String(s.scrollback);
  if (cursorBlink) cursorBlink.checked = !!s.cursorBlink;
}

function collectSettingsForm() {
  return {
    themeId: (document.getElementById('set-theme') || {}).value || 'tokyo-night',
    fontFamily: (document.getElementById('set-font-family') || {}).value || DEFAULT_TERMINAL_SETTINGS.fontFamily,
    fontSize: Number((document.getElementById('set-font-size') || {}).value || 13),
    scrollback: Number((document.getElementById('set-scrollback') || {}).value || 5000),
    cursorBlink: !!(document.getElementById('set-cursor-blink') || {}).checked,
  };
}

function openSettingsDialog() {
  fillSettingsForm();
  const mask = document.getElementById('dlg-settings-mask');
  if (mask) mask.classList.remove('hidden');
}

function closeSettingsDialog() {
  const mask = document.getElementById('dlg-settings-mask');
  if (mask) mask.classList.add('hidden');
}

function applySettingsFromDialog() {
  const next = saveTerminalSettings(collectSettingsForm());
  applySettingsToAllTerminals(next);
  closeSettingsDialog();
  if (typeof setStatus === 'function') setStatus('终端外观已更新');
}

Sshterm.BUILTIN_THEMES = BUILTIN_THEMES;
Sshterm.DEFAULT_TERMINAL_SETTINGS = DEFAULT_TERMINAL_SETTINGS;
Sshterm.loadTerminalSettings = loadTerminalSettings;
Sshterm.saveTerminalSettings = saveTerminalSettings;
Sshterm.getTerminalOptions = getTerminalOptions;
Sshterm.applySettingsToTerminal = applySettingsToTerminal;
Sshterm.applySettingsToAllTerminals = applySettingsToAllTerminals;
Sshterm.fillSettingsForm = fillSettingsForm;
Sshterm.collectSettingsForm = collectSettingsForm;
Sshterm.openSettingsDialog = openSettingsDialog;
Sshterm.closeSettingsDialog = closeSettingsDialog;
Sshterm.applySettingsFromDialog = applySettingsFromDialog;
